 $user=requireUser($auth);$method=$_SERVER['REQUEST_METHOD'];$body=requestBody();
 if($method==='GET'){$rows=$db->all('SELECT * FROM repair_records ORDER BY id DESC');$items=array_map(fn($r)=>['id'=>(int)$r['id'],'docNumber'=>$r['doc_number'],'productId'=>(int)$r['product_id'],'quantity'=>(int)$r['quantity'],'sendDate'=>$r['send_date'],'submittedBy'=>$r['submitted_by'],'repairShop'=>$r['repair_shop'],'issueDescription'=>$r['issue_description'],'status'=>$r['status'],'resultDate'=>$r['result_date'],'result'=>$r['result'],'technician'=>$r['technician'],'approver'=>$r['approver'],'resultNotes'=>$r['result_notes'],'resultDocNumber'=>$r['result_doc_number'],'voidReason'=>$r['void_reason']],$rows);jsonResponse(['repairRecords'=>$items]);}
 if($method==='POST'&&str_ends_with(parse_url($_SERVER['REQUEST_URI']??'',PHP_URL_PATH)?:'','/send')){$pid=(int)($body['productId']??0);$qty=(int)($body['quantity']??0);$date=trim((string)($body['date']??''));$submitted=trim((string)($body['submittedBy']??''));$issue=trim((string)($body['issueDescription']??''));$shop=trim((string)($body['repairShop']??''))?:'کارگاه تعمیرات داخلی';if($pid<=0||$qty<=0||$date===''||$submitted===''||$issue==='')jsonResponse(['error'=>'اطلاعات ارسال به تعمیر ناقص است'],400);$row=$db->transaction(function(Database $db)use($pid,$qty,$date,$submitted,$issue,$shop,$user){$p=$db->one('SELECT * FROM products WHERE id=? FOR UPDATE',[$pid]);if(!$p)throw new BusinessError('کالا یافت نشد',404);if(!(int)$p['active'])throw new BusinessError('این کالا بایگانی شده است');$snap=(new Business($db))->stockSnapshot($p);if($qty>$snap['available'])throw new BusinessError('تعداد قابل ارسال به تعمیر کافی نیست');$b=new Business($db);$doc=$b->nextDocNumber('repIn');$now=gmdate('c');$db->execute("INSERT INTO repair_records (doc_number,product_id,quantity,send_date,submitted_by,repair_shop,issue_description,status,created_by_user_id,created_at) VALUES (?,?,?,?,?,?,?,'در حال تعمیر',?,?)",[$doc,$pid,$qty,$date,$submitted,$shop,$issue,$user['id'],$now]);return $db->one('SELECT * FROM repair_records WHERE id=?',[$db->lastInsertId()]);});jsonResponse(['repairRecord'=>$row],201);}
